-- 104: 学术交流治理（主办会议、人员派出/接收）与期刊分区匹配库
BEGIN;

-- 1. 主办会议申请
CREATE TABLE IF NOT EXISTS "主办会议申请" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "会议名称" varchar(200) NOT NULL,
    "会议级别" varchar(50) NOT NULL,
    "主办单位" varchar(200) NOT NULL,
    "承办单位" varchar(200),
    "协办单位" varchar(200),
    "负责人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "归属部门编号" integer REFERENCES "部门"("编号"),
    "开始日期" date NOT NULL,
    "结束日期" date NOT NULL,
    "举办地点" varchar(200) NOT NULL,
    "预计参会人数" integer NOT NULL DEFAULT 50,
    "境外参会人数" integer NOT NULL DEFAULT 0,
    "经费预算" numeric(18,2) NOT NULL DEFAULT 0,
    "经费来源" varchar(200),
    "是否涉外" boolean NOT NULL DEFAULT FALSE,
    "议程附件路径" varchar(2000),
    "总结报告路径" varchar(2000),
    "实际参会人数" integer,
    "状态" varchar(30) NOT NULL DEFAULT '草稿',
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "审核意见" varchar(1000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_主办会议_日期" CHECK ("结束日期" >= "开始日期"),
    CONSTRAINT "ck_主办会议_人数" CHECK ("预计参会人数" > 0 AND "境外参会人数" >= 0),
    CONSTRAINT "ck_主办会议_预算" CHECK ("经费预算" >= 0),
    CONSTRAINT "ck_主办会议_级别" CHECK ("会议级别" IN ('国际','全国','省级','市级','院级')),
    CONSTRAINT "ck_主办会议_状态" CHECK ("状态" IN ('草稿','待审核','已批准','已驳回','已撤回','已举办','已总结'))
);
CREATE INDEX IF NOT EXISTS "ix_主办会议_状态日期" ON "主办会议申请" ("状态", "开始日期" DESC);

-- 2. 学术交流人员 (派出与接收)
CREATE TABLE IF NOT EXISTS "学术交流人员" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "交流方向" varchar(20) NOT NULL,
    "人员编号" integer REFERENCES "人员"("编号"),
    "外来人员姓名" varchar(100),
    "外来人员单位" varchar(200),
    "外来人员国籍" varchar(100),
    "外来人员职称" varchar(100),
    "交流类型" varchar(50) NOT NULL,
    "目的地或来访地" varchar(200) NOT NULL,
    "开始日期" date NOT NULL,
    "结束日期" date NOT NULL,
    "经费来源" varchar(200),
    "关联主办会议编号" bigint REFERENCES "主办会议申请"("编号") ON DELETE SET NULL,
    "状态" varchar(30) NOT NULL DEFAULT '草稿',
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "审核意见" varchar(1000),
    "成果总结路径" varchar(2000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_交流人员_方向" CHECK ("交流方向" IN ('派出','接收')),
    CONSTRAINT "ck_交流人员_日期" CHECK ("结束日期" >= "开始日期"),
    CONSTRAINT "ck_交流人员_类型" CHECK ("交流类型" IN ('访问学者','合作研究','进修','讲学','参会','短期交流')),
    CONSTRAINT "ck_交流人员_状态" CHECK ("状态" IN ('草稿','待审核','已批准','已驳回','已撤回','进行中','已完成')),
    CONSTRAINT "ck_交流人员_人员必填" CHECK (
        ("交流方向" = '派出' AND "人员编号" IS NOT NULL) OR
        ("交流方向" = '接收' AND "外来人员姓名" IS NOT NULL AND "外来人员单位" IS NOT NULL)
    )
);
CREATE INDEX IF NOT EXISTS "ix_交流人员_方向状态" ON "学术交流人员" ("交流方向", "状态", "开始日期" DESC);

-- 3. 期刊分区导入批次
CREATE TABLE IF NOT EXISTS "期刊分区导入批次" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "来源" varchar(50) NOT NULL,
    "年度" integer NOT NULL,
    "文件名" varchar(300) NOT NULL,
    "文件哈希" varchar(128) NOT NULL,
    "总行数" integer NOT NULL DEFAULT 0,
    "成功数" integer NOT NULL DEFAULT 0,
    "失败数" integer NOT NULL DEFAULT 0,
    "导入人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_期刊导入_来源年度哈希" UNIQUE ("来源", "年度", "文件哈希"),
    CONSTRAINT "ck_期刊导入_来源" CHECK ("来源" IN ('JCR','中科院分区','CSSCI','北大核心','EI','CSCD'))
);

-- 4. 期刊分区库
CREATE TABLE IF NOT EXISTS "期刊分区库" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "导入批次编号" bigint REFERENCES "期刊分区导入批次"("编号") ON DELETE SET NULL,
    "来源" varchar(50) NOT NULL,
    "年度" integer NOT NULL,
    "期刊名称" varchar(300) NOT NULL,
    "规范化名称" varchar(300) NOT NULL,
    "ISSN" varchar(50),
    "eISSN" varchar(50),
    "学科类别" varchar(100) NOT NULL DEFAULT '综合',
    "分区" varchar(50) NOT NULL,
    "影响因子" numeric(8,3),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_期刊分区_来源年度期刊学科" UNIQUE ("来源", "年度", "规范化名称", "学科类别"),
    CONSTRAINT "ck_期刊分区_来源" CHECK ("来源" IN ('JCR','中科院分区','CSSCI','北大核心','EI','CSCD'))
);
CREATE INDEX IF NOT EXISTS "ix_期刊分区_查询" ON "期刊分区库" ("规范化名称", "ISSN", "年度");

-- 5. 论文期刊分区匹配记录
CREATE TABLE IF NOT EXISTS "论文期刊分区匹配" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "论文编号" integer NOT NULL,
    "来源" varchar(50) NOT NULL,
    "年度" integer NOT NULL,
    "分区" varchar(50) NOT NULL,
    "影响因子" numeric(8,3),
    "匹配方式" varchar(30) NOT NULL,
    "确认状态" varchar(30) NOT NULL DEFAULT '待确认',
    "确认人编号" integer REFERENCES "人员"("编号"),
    "确认时间" timestamp without time zone,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_论文分区_确认状态" CHECK ("确认状态" IN ('待确认','已确认','已驳回'))
);
CREATE INDEX IF NOT EXISTS "ix_论文分区_论文" ON "论文期刊分区匹配" ("论文编号", "来源");

-- 6. 期刊分区匹配存储函数
CREATE OR REPLACE FUNCTION "fn_匹配期刊分区"(
    p_issn varchar,
    p_期刊名称 varchar,
    p_年度 integer
)
RETURNS TABLE (
    "来源" varchar(50),
    "年度" integer,
    "期刊名称" varchar(300),
    "分区" varchar(50),
    "影响因子" numeric(8,3),
    "匹配方式" varchar(30)
) LANGUAGE plpgsql AS $$
DECLARE
    v_norm varchar := lower(regexp_replace(COALESCE(p_期刊名称,''), '[[:punct:][:space:]]', '', 'g'));
    v_clean_issn varchar := replace(replace(COALESCE(p_issn,''), '-', ''), ' ', '');
BEGIN
    RETURN QUERY
    WITH matches AS (
        SELECT 
            q."来源", q."年度", q."期刊名称", q."分区", q."影响因子",
            CASE 
                WHEN (v_clean_issn <> '' AND (replace(q."ISSN",'-','') = v_clean_issn OR replace(q."eISSN",'-','') = v_clean_issn)) THEN 'ISSN精确'
                ELSE '名称规范匹配'
            END AS "匹配方式",
            ROW_NUMBER() OVER (
                PARTITION BY q."来源" 
                ORDER BY 
                    CASE WHEN (v_clean_issn <> '' AND (replace(q."ISSN",'-','') = v_clean_issn OR replace(q."eISSN",'-','') = v_clean_issn)) THEN 1 ELSE 2 END,
                    abs(q."年度" - COALESCE(p_年度, q."年度")) ASC,
                    q."年度" DESC
            ) as rn
        FROM "期刊分区库" q
        WHERE (v_clean_issn <> '' AND (replace(q."ISSN",'-','') = v_clean_issn OR replace(q."eISSN",'-','') = v_clean_issn))
           OR (v_norm <> '' AND q."规范化名称" = v_norm)
    )
    SELECT m."来源", m."年度", m."期刊名称", m."分区", m."影响因子", m."匹配方式"::varchar(30)
    FROM matches m
    WHERE m.rn = 1;
END;
$$;

