(217, 2, '期刊分区库', '科研办公/科研办公/期刊分区库.html', TRUE, '中科院/JCR/CSSCI/北大核心期刊分区导入与论文自动匹配')
ON CONFLICT ("编号") DO UPDATE SET "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "备注"=EXCLUDED."备注";

INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", p."编号" FROM "角色" r, (VALUES (216), (217)) AS p("编号")
WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=p."编号");

UPDATE "系统迁移版本"
SET "版本"=104, "脚本"='104_academic_exchange_and_journal_partition.sql',
    "检查摘要"='增加学术会议申请、派出接收管理、期刊分区库与分区自动匹配', "应用时间"=CURRENT_TIMESTAMP
